        # 调用时解析缺省：测试可在导入后补丁 CONFIG_IMPORT_MAX_OUTPUT_BYTES
        max_output_bytes = CONFIG_IMPORT_MAX_OUTPUT_BYTES
    try:
        with open(snapshot_path, "rb") as snapshot_handle:
            # 仅读取一个 SNAPSHOT；分块读取与字节边界沿用 config-export，
            # 原始字节（含空白）计入 IN，等于上限合法
            snapshot_raw = _read_limited(snapshot_handle, max_input_bytes)
            if snapshot_raw is None:
                _fail("input_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        snapshot = parse_json(snapshot_raw)
        # 键恰为 schema,config,sha256（键序不限）；schema 为整数 1
        if not isinstance(snapshot, dict) or frozenset(snapshot) != frozenset(
            SNAPSHOT_KEYS
        ):
            raise InvalidInput("bad snapshot")
        if not _is_int(snapshot["schema"]) or snapshot["schema"] != 1:
            raise InvalidInput("bad snapshot schema")
        config = snapshot["config"]
        # 按既有 port-security 契约全量解析校验（编码、JSON、语义）
        validate_security_config(config)
        # C：config 规范化后按紧凑 UTF-8 口径编码并加 LF
        canonical = _canonical(config)
        payload = _result_bytes(canonical)
        # sha256 为 C 的 SHA-256 小写 64 位十六进制；不符即非法输入
        digest = snapshot["sha256"]
        if (
            not isinstance(digest, str)
            or hashlib.sha256(payload).hexdigest() != digest
        ):
            raise InvalidInput("bad snapshot sha256")
        # 全部非法输入判定后，按 config-export 同一公式无副作用预演 S；
        # 等于上限合法，首次超过即停止，不触碰 OUTPUT
        _diff_size_charge(config, max_import_work)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except DiffWorkLimit:
        _fail("import_work_limit")
        return 5
    # C 含 LF 不得超过 OUT；等于上限合法，超限时绝不触碰 OUTPUT
    if len(payload) > max_output_bytes:
        _fail("output_limit")

