    fdb = {}  # (vlan, mac) -> [port, seen]
    work = 0
    for t, port, mac, vlan in events:
        work += len(fdb) + 1
        if work > limit:
            raise FdbWorkLimit
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        fdb[(vlan, mac)] = [port, t]


